import { normalizeElectorateName } from './electorate-names.js';
import {
  computeObservedSwing,
  computeSeatChance,
  DEFAULT_TAU,
  type SeatChance,
  type SeatPrior,
} from './seat-probability.js';
import type {
  ElectorateResults,
  WithLeaders,
  VotingResults,
} from './types.js';

/**
 * Notional results: the previous cycle's votes rebuilt on this cycle's
 * boundaries. Generated by `scripts/build-notional-baseline.mjs`, which is the
 * only writer; see `docs/voting-place-data.md` for the method and its
 * deliberate limits.
 */
export type BaselineSeat = {
  kind: 'general' | 'maori';
  votes: number;
  places: number;
  partyShare: Record<string, number>;
  candidateShare: Record<string, number>;
  partyCandidateShare?: Record<string, number>;
  /**
   * Enrolled electors in the source cycle, recovered from that seat's own file
   * (`total_votes_cast ÷ percent_votes_cast`). `null` when the seat came from a
   * same-name carry-over rather than place geometry.
   */
  enrolment?: number | null;
};

export type NotionalBaseline = {
  sourceYear: number;
  targetYear: number;
  method: string;
  tau: {
    transition: string;
    seats: number;
    meanMaxAbsDeviation: number;
    sdMaxAbsDeviation: number;
    maxAbsDeviation: number;
    /**
     * sd of each seat's departure from uniform national swing in the top-two
     * margin, in vote-share points. This is the number the model uses.
     */
    sdSwingDeviation?: number;
  } | null;
  coverage: {
    seats: number;
    placesLocated: number;
    placesSkipped: number;
    inSeatResults: number;
    outOfSeatResultsDropped?: number;
    seatsFromOwnPrior?: number;
    seatsApportioned?: number;
  };
  seats: Record<string, BaselineSeat>;
};

export type ElectorateResult = ElectorateResults & WithLeaders;

/** The seat's prior result on the current boundaries, or null. */
export function priorForSeat(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): SeatPrior | null {
  if (!baseline || !seatName) return null;
  const wanted = normalizeElectorateName(seatName);
  for (const [name, seat] of Object.entries(baseline.seats)) {
    if (normalizeElectorateName(name) !== wanted) continue;
    return {
      partyShare: seat.partyShare,
      candidateShare: seat.candidateShare,
      partyCandidateShare: seat.partyCandidateShare,
    };
  }
  return null;
}

/** The seat's enrolled electors in the baseline cycle, when recorded. */
export function enrolmentForSeat(
  baseline: NotionalBaseline | null,
  seatName: string | null | undefined
): number | null {
  if (!baseline || !seatName) return null;
  const wanted = normalizeElectorateName(seatName);
  for (const [name, seat] of Object.entries(baseline.seats)) {
    if (normalizeElectorateName(name) !== wanted) continue;
    return seat.enrolment && seat.enrolment > 0 ? seat.enrolment : null;
  }
  return null;
}

/**
 * How far seats typically stray from uniform national swing, as a standard
 * deviation of vote share. The fallback is used only when the baseline carries
 * no measurement.
 */
export function tauFor(baseline: NotionalBaseline | null): number {
  const measured =
    baseline?.tau?.sdSwingDeviation ?? baseline?.tau?.sdMaxAbsDeviation;
  return measured ? measured / 100 : DEFAULT_TAU;
}

/** Candidate votes folded up to the party that stood them. */
function candidateVotesByParty(
  votes: { candidate: string; party?: string; votes: number }[]
): VotingResults[] {
  const byParty = new Map<string, number>();
  for (const vote of votes) {
    if (!vote.party) continue;
    byParty.set(vote.party, (byParty.get(vote.party) ?? 0) + vote.votes);
  }
  return [...byParty].map(([candidate, count]) => ({
    candidate,
    votes: count,
  })) as VotingResults[];
}

/**
 * National swing measured across the seats counted so far.
 *
 * Measured from the night's own seats rather than a published table: it needs
 * no prior national result, and it corrects itself as the advance-heavy early
 * seats stop being the whole sample. The seat is decided on the candidate vote,
 * so the swing is measured there too.
 */
export function nationalSwingOf(
  baseline: NotionalBaseline | null,
  electorates: ElectorateResult[]
): Record<string, number> {
  if (!baseline) return {};
  return computeObservedSwing(
    electorates.map((result) => ({
      prior: priorForSeat(baseline, result.electorateName),
      parties: candidateVotesByParty(result.candidateVotes),
      votesCounted: result.votesCounted,
    }))
  );
}

/** The chance of winning the seat, given a baseline and a swing. */
export function seatChanceFor(
  result: ElectorateResult,
  baseline: NotionalBaseline | null,
  nationalSwing: Record<string, number>,
  electionYear: string | number | null | undefined
): SeatChance {
  return computeSeatChance({
    candidates: result.candidateVotes.map((c) => ({
      name: c.candidate,
      party: c.party,
      votes: c.votes,
    })),
    votesCounted: result.votesCounted,
    percentVotesCast: result.percentVotesCast,
    enrolment:
      enrolmentForSeat(baseline, result.electorateName) ?? undefined,
    electionYear: electionYear ? Number(electionYear) : null,
    prior: priorForSeat(baseline, result.electorateName),
    nationalSwing,
    tau: tauFor(baseline),
  });
}

/**
 * Build the per-seat chance lookup for one payload.
 *
 * The swing depends on every seat at once, so it is computed here rather than
 * per result. Returns `undefined` when no baseline is available, in which case
 * callers fall back to count-only language: a chance with no prior is a number
 * pretending to be informed.
 */
export function chanceLookupFor(
  baseline: NotionalBaseline | null,
  electorates: ElectorateResult[],
  electionYear: string | number | null | undefined
): ((result: ElectorateResult) => SeatChance) | undefined {
  if (!baseline) return undefined;
  const swing = nationalSwingOf(baseline, electorates);
  return (result) => seatChanceFor(result, baseline, swing, electionYear);
}
